type OrderState = 'created' | 'paid' | 'shipped' | 'delivered' | 'cancelled' | 'refunded';

const VALID_TRANSITIONS: Record<OrderState, OrderState[]> = {
  created: ['paid', 'cancelled'],
  paid: ['shipped', 'refunded', 'cancelled'],
  shipped: ['delivered', 'cancelled'],
  delivered: ['refunded'],
  cancelled: ['refunded'],
  refunded: [],
};

class OrderStateMachine {
  private state: OrderState = 'created';

  getState(): OrderState {
    return this.state;
  }

  canTransitionTo(nextState: OrderState): boolean {
    return VALID_TRANSITIONS[this.state].includes(nextState);
  }

  transitionTo(nextState: OrderState): void {
    if (!VALID_TRANSITIONS[this.state].includes(nextState)) {
      throw new Error(
        `Invalid transition: ${this.state} → ${nextState}. ` +
        `Valid transitions from ${this.state}: ${VALID_TRANSITIONS[this.state].join(', ')}`
      );
    }
    this.state = nextState;
  }
}

// Test cases
const order = new OrderStateMachine();

console.log('Initial state:', order.getState()); // created

// Valid transitions
order.transitionTo('paid');
console.log('After payment:', order.getState()); // paid

order.transitionTo('shipped');
console.log('After shipping:', order.getState()); // shipped

order.transitionTo('delivered');
console.log('After delivery:', order.getState()); // delivered

order.transitionTo('refunded');
console.log('After refund:', order.getState()); // refunded

// Test invalid transition
const order2 = new OrderStateMachine();
order2.transitionTo('paid');

try {
  order2.transitionTo('delivered'); // skip shipped
  console.log('This should not print');
} catch (e) {
  console.log('\nCaught invalid transition:', (e as Error).message);
}

// Test canTransitionTo
const order3 = new OrderStateMachine();
console.log('\nFrom created, can go to paid?', order3.canTransitionTo('paid')); // true
console.log('From created, can go to shipped?', order3.canTransitionTo('shipped')); // false

