```typescript
type OrderState = 'created' | 'paid' | 'shipped' | 'delivered' | 'cancelled' | 'refunded';

const VALID_TRANSITIONS: Record<OrderState, OrderState[]> = {
  created: ['paid', 'cancelled'],
  paid: ['shipped', 'refunded', 'cancelled'],
  shipped: ['delivered', 'cancelled'],
  delivered: ['refunded'],
  cancelled: ['refunded'],
  refunded: [],
};

class OrderStateMachine {
  private state: OrderState = 'created';

  getState(): OrderState {
    return this.state;
  }

  canTransitionTo(nextState: OrderState): boolean {
    return VALID_TRANSITIONS[this.state].includes(nextState);
  }

  transitionTo(nextState: OrderState): void {
    if (!VALID_TRANSITIONS[this.state].includes(nextState)) {
      throw new Error(
        `Invalid transition: ${this.state} → ${nextState}. ` +
        `Valid transitions from ${this.state}: ${VALID_TRANSITIONS[this.state].join(', ')}`
      );
    }
    this.state = nextState;
  }
}
```

**Legal transitions:**
- `created` → paid, cancelled
- `paid` → shipped, refunded, cancelled
- `shipped` → delivered, cancelled
- `delivered` → refunded
- `cancelled` → refunded
- `refunded` → (terminal state)

**Usage:**
```typescript
const order = new OrderStateMachine();
order.transitionTo('paid');    // ✓
order.transitionTo('shipped'); // ✓
order.transitionTo('delivered'); // ✓

order.transitionTo('refunded'); // ✓
order.transitionTo('paid');     // ✗ throws error

order.canTransitionTo('refunded'); // true
```

Invalid transitions throw with clear error messages. `canTransitionTo()` lets you check before attempting.
